// ===== LGM SYNC CONFIG (La Growth Machine -> HubSpot -> Supabase) =====
// The LinkedIn URL lives on linkedin_profile__c in this portal. hs_linkedin_url
// does NOT exist here, and HubSpot answers an unknown property name with silently
// empty results instead of an error — verify any change via MCP search_properties.
const LINKEDIN_PROP = 'linkedin_profile__c';
const NOTE_MARKER   = 'LGM Response';  // first line of every note; HubSpot workflows key on it
const SNIPPET_LEN   = 240;             // reply_snippet length, matches the Responded page
const TEXT_PROP_LEN = 2000;            // cap for lgm_last_response_text

// LGM lets you shape the webhook body per campaign, so there is no one schema.
// Every field is resolved against candidate paths, first hit wins. Once you have
// captured a real payload, cut each list down to the single path that matched.
const FIELD_PATHS = {
  event_id:  ['event_id','id','message.id','message_id','reply.id'],
  text:      ['message.text','message.body','reply.text','reply.body','text','body','content'],
  date:      ['message.date','message.created_at','reply.date','responded_at','date','timestamp'],
  channel:   ['channel','message.channel','reply.channel','type','source'],
  email:     ['lead.email','contact.email','email','lead.emails.0'],
  firstname: ['lead.firstname','lead.first_name','contact.firstname','firstname','first_name'],
  lastname:  ['lead.lastname','lead.last_name','contact.lastname','lastname','last_name'],
  linkedin:  ['lead.linkedin_url','lead.linkedin','lead.profile_url','linkedin_url'],
  lead_id:   ['lead.id','lead_id'],
  campaign:  ['campaign.name','campaign_name','campaign'],
  identity:  ['identity.name','identity','sender.name'],
  lead_url:  ['lead.url','lead.lgm_url','lead_url']
};

const src = $input.first().json || {};
// The Webhook node nests the posted body under .body; a manual/pinned run passes it flat.
const payload = (src.body && typeof src.body === 'object') ? src.body : src;

return [{ json: { LINKEDIN_PROP, NOTE_MARKER, SNIPPET_LEN, TEXT_PROP_LEN, FIELD_PATHS, payload } }];

const cfg = $input.first().json;
const p = cfg.payload || {};

const dig = (o, path) => path.split('.').reduce((cur, part) => {
  if (cur == null) return null;
  if (Array.isArray(cur)) return /^\d+$/.test(part) ? cur[Number(part)] : null;
  return typeof cur === 'object' ? cur[part] : null;
}, o);
const pick = (paths) => {
  for (const path of paths) {
    const v = dig(p, path);
    if (v == null) continue;
    if (typeof v === 'string' && !v.trim()) continue;
    return v;
  }
  return null;
};
const str = (v) => (v == null ? null : (String(v).trim() || null));

// The same URL can receive a campaign's whole event feed; only replies become notes.
const markers = [pick(['event','event_type','type','action','trigger']), dig(p, 'message.direction')]
  .filter(v => v != null).map(v => String(v).toLowerCase());
const isReply = markers.length === 0 || markers.some(m => /repl|respon|inbound|received|answer/.test(m));

const text = str(pick(cfg.FIELD_PATHS.text));
if (!isReply || !text) {
  return [{ json: { skip: true, reason: !isReply ? 'not a reply event' : 'no response text in payload' } }];
}

// Timestamps arrive as ISO strings, seconds, or milliseconds.
const rawDate = pick(cfg.FIELD_PATHS.date);
let ts = new Date();
if (rawDate != null) {
  if (typeof rawDate === 'number' || /^\d+$/.test(String(rawDate))) {
    const n = Number(rawDate);
    ts = new Date(n > 1e12 ? n : n * 1000);
  } else {
    const parsed = new Date(String(rawDate));
    if (!isNaN(parsed.getTime())) ts = parsed;
  }
}

const ALIAS = { linkedin_message:'linkedin', linkedin_dm:'linkedin', li:'linkedin', inmail:'linkedin', mail:'email', 'e-mail':'email' };
let channel = (str(pick(cfg.FIELD_PATHS.channel)) || 'linkedin').toLowerCase();
channel = ALIAS[channel] || channel;

const email = (str(pick(cfg.FIELD_PATHS.email)) || '').toLowerCase() || null;
const linkedin = str(pick(cfg.FIELD_PATHS.linkedin));
const name = [str(pick(cfg.FIELD_PATHS.firstname)), str(pick(cfg.FIELD_PATHS.lastname))].filter(Boolean).join(' ') || null;

// Idempotency key. Hashing text and timestamp collapses webhook retries while
// still letting a genuine second reply from the same lead through as its own event.
let eventId = str(pick(cfg.FIELD_PATHS.event_id));
if (!eventId) {
  const basis = [str(pick(cfg.FIELD_PATHS.lead_id)), email, ts.toISOString(), text].join('|');
  let h = 5381;
  for (let i = 0; i < basis.length; i++) h = ((h * 33) ^ basis.charCodeAt(i)) >>> 0;
  eventId = 'lgm-' + h.toString(16);
}

if (!email && !linkedin) {
  return [{ json: { skip: true, eventId, reason: 'payload carries no email or LinkedIn URL to match a contact on' } }];
}

// One search with two filterGroups — HubSpot ORs the groups: email OR LinkedIn handle.
const groups = [];
if (email) groups.push({ filters: [{ propertyName: 'email', operator: 'EQ', value: email }] });
if (linkedin) {
  const handle = String(linkedin).replace(/\/+$/, '').split('/').pop();
  if (handle) groups.push({ filters: [{ propertyName: cfg.LINKEDIN_PROP, operator: 'CONTAINS_TOKEN', value: handle }] });
}

return [{ json: {
  skip: false, eventId, text, channel, email, linkedin, name,
  respondedAt: ts.toISOString(),
  leadId: str(pick(cfg.FIELD_PATHS.lead_id)),
  campaign: str(pick(cfg.FIELD_PATHS.campaign)),
  identity: str(pick(cfg.FIELD_PATHS.identity)),
  leadUrl: str(pick(cfg.FIELD_PATHS.lead_url)),
  searchBody: { filterGroups: groups, properties: ['email','lgm_response_count','lgm_last_response_date'], limit: 1 }
} }];

const cfg  = $('Config').first().json;
const ev   = $('Normalize').first().json;
const res  = $input.first().json || {};
const hit  = (res.results || [])[0] || null;

if (!hit) {
  return [{ json: Object.assign({}, ev, { found: false,
    reason: 'no matching HubSpot contact for ' + (ev.email || ev.linkedin || 'this lead') }) }];
}

const props = hit.properties || {};
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const meta = [];
if (ev.campaign) meta.push('Campaign: ' + esc(ev.campaign));
if (ev.name)     meta.push('Lead: ' + esc(ev.name));
if (ev.identity) meta.push('Identity: ' + esc(ev.identity));
meta.push('Received: ' + ev.respondedAt.slice(0, 16).replace('T', ' ') + ' UTC');

const footer = ['Source: La Growth Machine'];
if (ev.leadUrl)  footer.push('<a href="' + esc(ev.leadUrl) + '">Open lead in LGM</a>');
if (ev.linkedin) footer.push('<a href="' + esc(ev.linkedin) + '">LinkedIn profile</a>');

// The marker is the first thing in the body so the note is unmistakable both in
// the timeline and to anything filtering note bodies over the API.
const noteBody = '<b>' + esc(cfg.NOTE_MARKER) + '</b> &mdash; ' + esc(ev.channel) + '<br>' +
  meta.join('<br>') + '<hr>' + esc(ev.text).replace(/\n/g, '<br>') + '<hr>' +
  '<i>' + footer.join(' &middot; ') + '</i>';

const ms = Date.parse(ev.respondedAt);

let count = parseInt(props.lgm_response_count, 10);
if (!isFinite(count)) count = 0;
const patch = { lgm_responded: 'true', lgm_response_count: count + 1 };

// HubSpot returns datetime properties as ISO strings, older exports as epoch ms.
// Only move the "last response" fields forward, so a replay of an older reply
// never overwrites a newer one.
const prevRaw = props.lgm_last_response_date;
let prev = NaN;
if (prevRaw != null && prevRaw !== '') {
  prev = /^\d+$/.test(String(prevRaw)) ? Number(prevRaw) : Date.parse(String(prevRaw));
}
if (!isFinite(prev) || ms >= prev) {
  patch.lgm_last_response_date = ms;
  patch.lgm_last_response_channel = ev.channel;
  if (ev.campaign) patch.lgm_last_response_campaign = ev.campaign;
  patch.lgm_last_response_text = ev.text.slice(0, cfg.TEXT_PROP_LEN);
}

const sqlStr = (v) => (v == null || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'");

return [{ json: Object.assign({}, ev, {
  found: true,
  contactId: String(hit.id),
  // Asked before we write anything: LGM retries a webhook until it gets a 2xx,
  // and without this guard every retry would mint a second note.
  seenSql: 'SELECT count(*)::int AS seen FROM linkedin_replies WHERE lgm_event_id = ' + sqlStr(ev.eventId) + ';',
  notePayload: {
    properties: { hs_timestamp: ms, hs_note_body: noteBody },
    associations: [{ to: { id: String(hit.id) },
      types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 202 }] }]
  },
  contactPatch: { properties: patch }
}) }];

const cfg   = $('Config').first().json;
const ev    = $('Resolve Contact').first().json;
const note  = $('Create Note').first().json || {};
const assoc = $input.first().json || {};

// The company association drives the Responded page, which groups by company.
const target = (assoc.results || [])[0] || {};
const companyId = target.toObjectId || target.id || null;

const esc = (v) => (v == null || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'");
const num = (v) => { const n = Number(v); return (v != null && v !== '' && isFinite(n)) ? String(Math.trunc(n)) : 'NULL'; };

const noteId = note.id || null;
if (!noteId) throw new Error('HubSpot returned no note id — refusing to write a reply row with no note_id');

const snippet = ev.text.replace(/\s+/g, ' ').trim().slice(0, cfg.SNIPPET_LEN);

const cols = 'note_id,date,contact_id,contact_name,company_id,message,reply_snippet,campaign_name,lgm_event_id';
const vals = [num(noteId), esc(ev.respondedAt.slice(0, 10)), num(ev.contactId), esc(ev.name),
              num(companyId), esc(ev.text), esc(snippet), esc(ev.campaign), esc(ev.eventId)].join(',');

const sql = [
  'BEGIN;',
  'INSERT INTO linkedin_replies (' + cols + ') VALUES (' + vals + ')',
  'ON CONFLICT (note_id) DO UPDATE SET date=EXCLUDED.date, contact_id=EXCLUDED.contact_id,',
  '  contact_name=EXCLUDED.contact_name, company_id=EXCLUDED.company_id, message=EXCLUDED.message,',
  '  reply_snippet=EXCLUDED.reply_snippet, campaign_name=EXCLUDED.campaign_name,',
  '  lgm_event_id=EXCLUDED.lgm_event_id;',
  'COMMIT;'
].join('\n');

return [{ json: { sql, noteId: String(noteId), companyId: companyId ? String(companyId) : null,
                  contactId: ev.contactId, eventId: ev.eventId, status: 'synced' } }];
